const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Rate limiting state
const rateLimits = new Map();

function rateLimit(windowMs, maxRequests) {
  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();
    const windowStart = now - windowMs;
    let record = rateLimits.get(key);
    if (!record || record.windowStart < windowStart) {
      record = { windowStart: now, count: 0 };
    }
    record.count++;
    rateLimits.set(key, record);
    if (record.count > maxRequests) {
      return res.status(429).json({ error: 'Rate limited' });
    }
    next();
  };
}

// Authentication middleware
async function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing authorization' });
  }
  const token = authHeader.slice(7);
  if (typeof token !== 'string' || token.length < 16 || token.length > 256) {
    return res.status(401).json({ error: 'Invalid token format' });
  }
  const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
  try {
    const result = await pool.query(
      'SELECT user_id, tenant_id, permissions FROM api_tokens WHERE token_hash = $1 AND revoked = false AND expires_at > NOW()',
      [tokenHash]
    );
    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'Invalid or expired token' });
    }
    req.auth = result.rows[0];
    next();
  } catch (err) {
    return res.status(500).json({ error: 'Authentication error' });
  }
}

// Secure pagination helper
function parsePagination(query) {
  const page = parseInt(query.page, 10) || 1;
  const pageSize = parseInt(query.page_size, 10) || 20;

  // Clamp page size
  const safePageSize = Math.min(Math.max(pageSize, 1), 100);

  // Calculate offset using safe integer arithmetic
  const safePage = Math.min(Math.max(page, 1), 10000);
  const offset = (safePage - 1) * safePageSize;

  return { limit: safePageSize, offset };
}

// Permission check
function requirePermission(permission) {
  return (req, res, next) => {
    const perms = req.auth.permissions;
    if (!Array.isArray(perms) || !perms.includes(permission)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// Document access control - checks document visibility
async function checkDocumentAccess(tenantId, documentId, userId) {
  const result = await pool.query(
    `SELECT id, tenant_id, visibility, owner_id FROM documents 
     WHERE id = $1 AND tenant_id = $2`,
    [documentId, tenantId]
  );
  if (result.rows.length === 0) return null;
  const doc = result.rows[0];

  // Documents can be 'private' (owner only), 'team' (same tenant), or 'public'
  if (doc.visibility === 'private' && doc.owner_id !== userId) {
    return null;
  }
  return doc;
}

// Search documents endpoint
app.get('/api/documents/search', rateLimit(60000, 100), authenticate, requirePermission('documents:read'), async (req, res) => {
  try {
    const { q, category, status, date_from, date_to } = req.query;
    const { limit, offset } = parsePagination(req.query);

    let conditions = ['d.tenant_id = $1'];
    let params = [req.auth.tenant_id];
    let paramIndex = 2;

    // Visibility filter - user can see their own private docs + team docs
    conditions.push(`(d.visibility != 'private' OR d.owner_id = $${paramIndex})`);
    params.push(req.auth.user_id);
    paramIndex++;

    // Soft-delete filter
    conditions.push(`d.deleted_at IS NULL`);

    if (q && typeof q === 'string' && q.length <= 200) {
      conditions.push(`d.search_vector @@ plainto_tsquery('english', $${paramIndex})`);
      params.push(q);
      paramIndex++;
    }

    if (category && typeof category === 'string' && /^[a-z_]{1,30}$/.test(category)) {
      conditions.push(`d.category = $${paramIndex}`);
      params.push(category);
      paramIndex++;
    }

    const VALID_STATUSES = ['draft', 'published', 'archived', 'review'];
    if (status && VALID_STATUSES.includes(status)) {
      conditions.push(`d.status = $${paramIndex}`);
      params.push(status);
      paramIndex++;
    }

    if (date_from && /^\d{4}-\d{2}-\d{2}$/.test(date_from)) {
      conditions.push(`d.created_at >= $${paramIndex}`);
      params.push(date_from);
      paramIndex++;
    }

    if (date_to && /^\d{4}-\d{2}-\d{2}$/.test(date_to)) {
      conditions.push(`d.created_at <= $${paramIndex}`);
      params.push(date_to);
      paramIndex++;
    }

    // Sort handling
    const SORT_FIELDS = { 'created_at': 'd.created_at', 'updated_at': 'd.updated_at', 'title': 'd.title' };
    const sortField = SORT_FIELDS[req.query.sort] || 'd.created_at';
    const sortDir = req.query.order === 'asc' ? 'ASC' : 'DESC';

    const queryText = `
      SELECT d.id, d.title, d.category, d.status, d.visibility, d.created_at, d.updated_at,
             ts_rank(d.search_vector, plainto_tsquery('english', COALESCE($${paramIndex}, ''))) as relevance
      FROM documents d
      WHERE ${conditions.join(' AND ')}
      ORDER BY ${sortField} ${sortDir}
      LIMIT $${paramIndex + 1} OFFSET $${paramIndex + 2}`;

    params.push(q || '', limit, offset);

    const result = await pool.query(queryText, params);

    // Count query
    const countQuery = `SELECT COUNT(*) FROM documents d WHERE ${conditions.join(' AND ')}`;
    const countResult = await pool.query(countQuery, params.slice(0, paramIndex - 1));

    res.json({
      documents: result.rows,
      pagination: { page: Math.floor(offset / limit) + 1, page_size: limit, total: parseInt(countResult.rows[0].count) }
    });
  } catch (err) {
    res.status(500).json({ error: 'Search failed' });
  }
});

// Share document endpoint
app.post('/api/documents/:id/share', rateLimit(60000, 30), authenticate, requirePermission('documents:write'), async (req, res) => {
  try {
    const docId = req.params.id;
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(docId)) {
      return res.status(400).json({ error: 'Invalid document ID' });
    }

    const { target_user_id, permission_level } = req.body;

    if (!target_user_id || typeof target_user_id !== 'string') {
      return res.status(400).json({ error: 'Invalid target user' });
    }
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(target_user_id)) {
      return res.status(400).json({ error: 'Invalid target user ID format' });
    }

    const VALID_PERMISSIONS = ['view', 'comment', 'edit'];
    if (!VALID_PERMISSIONS.includes(permission_level)) {
      return res.status(400).json({ error: 'Invalid permission level' });
    }

    // Verify ownership
    const doc = await pool.query(
      'SELECT id, owner_id, tenant_id FROM documents WHERE id = $1 AND tenant_id = $2',
      [docId, req.auth.tenant_id]
    );

    if (doc.rows.length === 0) {
      return res.status(404).json({ error: 'Document not found' });
    }

    if (doc.rows[0].owner_id !== req.auth.user_id) {
      return res.status(403).json({ error: 'Only document owner can share' });
    }

    // Verify target user is in same tenant
    const targetUser = await pool.query(
      'SELECT id FROM users WHERE id = $1 AND tenant_id = $2',
      [target_user_id, req.auth.tenant_id]
    );

    if (targetUser.rows.length === 0) {
      return res.status(404).json({ error: 'Target user not found' });
    }

    // Upsert share
    await pool.query(
      `INSERT INTO document_shares (document_id, user_id, permission_level, granted_by)
       VALUES ($1, $2, $3, $4)
       ON CONFLICT (document_id, user_id) DO UPDATE SET permission_level = $3, granted_by = $4, updated_at = NOW()`,
      [docId, target_user_id, permission_level, req.auth.user_id]
    );

    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Share operation failed' });
  }
});

// Bulk export endpoint
app.post('/api/documents/export', rateLimit(60000, 5), authenticate, requirePermission('documents:export'), async (req, res) => {
  try {
    const { document_ids, format } = req.body;

    if (!Array.isArray(document_ids) || document_ids.length === 0 || document_ids.length > 50) {
      return res.status(400).json({ error: 'Provide 1-50 document IDs' });
    }

    const VALID_FORMATS = ['pdf', 'csv', 'json'];
    if (!VALID_FORMATS.includes(format)) {
      return res.status(400).json({ error: 'Invalid export format' });
    }

    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    const validIds = document_ids.filter(id => typeof id === 'string' && uuidRegex.test(id));

    if (validIds.length === 0) {
      return res.status(400).json({ error: 'No valid document IDs' });
    }

    // Build parameterized IN clause
    const placeholders = validIds.map((_, i) => `$${i + 3}`);
    const query = `
      SELECT d.id, d.title, d.content, d.category, d.status, d.created_at
      FROM documents d
      LEFT JOIN document_shares ds ON ds.document_id = d.id AND ds.user_id = $2
      WHERE d.tenant_id = $1
        AND d.id IN (${placeholders.join(',')})
        AND d.deleted_at IS NULL
        AND (d.visibility != 'private' OR d.owner_id = $2 OR ds.user_id IS NOT NULL)`;

    const result = await pool.query(query, [req.auth.tenant_id, req.auth.user_id, ...validIds]);

    // Queue export job
    const jobId = crypto.randomUUID();
    await pool.query(
      'INSERT INTO export_jobs (id, user_id, tenant_id, document_ids, format, status) VALUES ($1, $2, $3, $4, $5, $6)',
      [jobId, req.auth.user_id, req.auth.tenant_id, JSON.stringify(result.rows.map(r => r.id)), format, 'pending']
    );

    res.json({ job_id: jobId, document_count: result.rows.length });
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Webhook configuration endpoint
app.put('/api/webhooks/:id', rateLimit(60000, 20), authenticate, requirePermission('webhooks:manage'), async (req, res) => {
  try {
    const webhookId = req.params.id;
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(webhookId)) {
      return res.status(400).json({ error: 'Invalid webhook ID' });
    }

    const { url, events, secret, active } = req.body;

    // Validate URL
    if (url !== undefined) {
      if (typeof url !== 'string' || url.length > 2048) {
        return res.status(400).json({ error: 'Invalid URL' });
      }
      try {
        const parsed = new URL(url);
        if (!['https:'].includes(parsed.protocol)) {
          return res.status(400).json({ error: 'Only HTTPS URLs allowed' });
        }
        // Block private IPs
        const hostname = parsed.hostname;
        if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname.startsWith('10.') || hostname.startsWith('192.168.') || hostname.startsWith('172.') || hostname === '0.0.0.0' || hostname === '::1' || hostname.endsWith('.local') || hostname.endsWith('.internal')) {
          return res.status(400).json({ error: 'Private URLs not allowed' });
        }
      } catch {
        return res.status(400).json({ error: 'Invalid URL format' });
      }
    }

    // Validate events
    const VALID_EVENTS = ['document.created', 'document.updated', 'document.deleted', 'document.shared'];
    if (events !== undefined) {
      if (!Array.isArray(events) || events.some(e => !VALID_EVENTS.includes(e))) {
        return res.status(400).json({ error: 'Invalid events' });
      }
    }

    // Verify ownership
    const existing = await pool.query(
      'SELECT id FROM webhooks WHERE id = $1 AND tenant_id = $2',
      [webhookId, req.auth.tenant_id]
    );

    if (existing.rows.length === 0) {
      return res.status(404).json({ error: 'Webhook not found' });
    }

    // Build update dynamically but safely
    const updates = [];
    const updateParams = [];
    let idx = 1;

    if (url !== undefined) { updates.push(`url = $${idx}`); updateParams.push(url); idx++; }
    if (events !== undefined) { updates.push(`events = $${idx}`); updateParams.push(JSON.stringify(events)); idx++; }
    if (secret !== undefined && typeof secret === 'string' && secret.length >= 16 && secret.length <= 128) {
      const secretHash = crypto.createHash('sha256').update(secret).digest('hex');
      updates.push(`secret_hash = $${idx}`); updateParams.push(secretHash); idx++;
    }
    if (typeof active === 'boolean') { updates.push(`active = $${idx}`); updateParams.push(active); idx++; }

    if (updates.length === 0) {
      return res.status(400).json({ error: 'No valid fields to update' });
    }

    updates.push(`updated_at = NOW()`);
    updateParams.push(webhookId, req.auth.tenant_id);

    await pool.query(
      `UPDATE webhooks SET ${updates.join(', ')} WHERE id = $${idx} AND tenant_id = $${idx + 1}`,
      updateParams
    );

    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Update failed' });
  }
});

// Document version history
app.get('/api/documents/:id/versions', rateLimit(60000, 60), authenticate, requirePermission('documents:read'), async (req, res) => {
  try {
    const docId = req.params.id;
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(docId)) {
      return res.status(400).json({ error: 'Invalid document ID' });
    }

    // Check access
    const doc = await checkDocumentAccess(req.auth.tenant_id, docId, req.auth.user_id);
    if (!doc) {
      return res.status(404).json({ error: 'Document not found' });
    }

    const { limit, offset } = parsePagination(req.query);

    const versions = await pool.query(
      `SELECT v.id, v.version_number, v.created_at, v.created_by, u.display_name as author_name,
              v.change_summary, length(v.content) as content_length
       FROM document_versions v
       JOIN users u ON u.id = v.created_by
       WHERE v.document_id = $1
       ORDER BY v.version_number DESC
       LIMIT $2 OFFSET $3`,
      [docId, limit, offset]
    );

    res.json({ versions: versions.rows });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch versions' });
  }
});

// Admin: Tenant usage report
app.get('/api/admin/usage', rateLimit(60000, 10), authenticate, requirePermission('admin:reports'), async (req, res) => {
  try {
    const { metric, period } = req.query;

    const VALID_METRICS = ['documents', 'storage', 'api_calls', 'users'];
    const VALID_PERIODS = ['day', 'week', 'month'];

    if (!VALID_METRICS.includes(metric)) {
      return res.status(400).json({ error: 'Invalid metric' });
    }
    if (!VALID_PERIODS.includes(period)) {
      return res.status(400).json({ error: 'Invalid period' });
    }

    // The metric maps to a specific pre-defined query
    const queries = {
      documents: `SELECT date_trunc($1, created_at) as period, COUNT(*) as value FROM documents WHERE tenant_id = $2 AND created_at > NOW() - INTERVAL '90 days' GROUP BY 1 ORDER BY 1`,
      storage: `SELECT date_trunc($1, recorded_at) as period, MAX(bytes_used) as value FROM storage_metrics WHERE tenant_id = $2 AND recorded_at > NOW() - INTERVAL '90 days' GROUP BY 1 ORDER BY 1`,
      api_calls: `SELECT date_trunc($1, called_at) as period, COUNT(*) as value FROM api_call_log WHERE tenant_id = $2 AND called_at > NOW() - INTERVAL '90 days' GROUP BY 1 ORDER BY 1`,
      users: `SELECT date_trunc($1, created_at) as period, COUNT(*) as value FROM users WHERE tenant_id = $2 AND created_at > NOW() - INTERVAL '90 days' GROUP BY 1 ORDER BY 1`
    };

    const result = await pool.query(queries[metric], [period, req.auth.tenant_id]);
    res.json({ metric, period, data: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Report generation failed' });
  }
});

